from fastapi import HTTPException

from app.modules.videos.media import byte_range


@pytest.mark.parametrize(
    "header,result",
    [
        (None, None),
        ("bytes=0-9", (0, 9)),
        ("bytes=90-999", (90, 99)),
        ("bytes=-200", (0, 99)),
        ("bytes=99-", (99, 99)),
    ],
)
def test_valid_ranges(header, result):
    assert byte_range(header, 100) == result


@pytest.mark.parametrize(
