        "bytes=-",
        "bytes=-0",
        "bytes=100-",
        "bytes=5-1",
        "bytes=0-1,2-3",
        "items=0-5",
        "bytes= 0-1",
        "bytes=１２-９９",
    ],
)
def test_invalid_ranges(header):
    with pytest.raises(HTTPException) as error:
